mapper.select:
SELECT ms.*, m.material_name, m.material_code, m.material_type, m.specification, m.unit, m.moisture_proof, m.warning_stock FROM material_stock ms LEFT JOIN material m ON ms.material_id = m.id
ms.deleted = 0
AND m.material_name LIKE CONCAT('%', #{materialName}, '%')
AND m.material_code LIKE CONCAT('%', #{materialCode}, '%')
AND m.material_type = #{materialType}
AND ms.stock_status = #{stockStatus}
AND ms.warehouse = #{warehouse}
AND m.moisture_proof = 1 AND ms.moisture_check_time < DATE_SUB(NOW(), INTERVAL 7 DAY)
ORDER BY ms.create_time DESC
